import base64
import http.server
import os
import tempfile
from urllib.parse import unquote, urlsplit

HOST = "0.0.0.0"
PORT = 8080
RECORDS_DIR = "/var/lib/builder/records"


os.makedirs(RECORDS_DIR, mode=0o755, exist_ok=True)


def record_filename(record_id):
    encoded = base64.urlsafe_b64encode(record_id.encode("utf-8")).decode("ascii")
    return os.path.join(RECORDS_DIR, encoded)


class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format, *args):
        pass

    def send_bytes(self, status, body):
        self.send_response(status)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def record_id(self):
        parsed = urlsplit(self.path)
        if parsed.query or parsed.fragment:
            return None
        prefix = "/records/"
        if not parsed.path.startswith(prefix):
            return None
        encoded_id = parsed.path[len(prefix):]
        if not encoded_id or "/" in encoded_id:
            return None
        try:
            return unquote(encoded_id, errors="strict")
        except UnicodeDecodeError:
            return None

    def do_GET(self):
        if urlsplit(self.path).path == "/health":
            self.send_bytes(200, b"ready")
            return

        record_id = self.record_id()
        if record_id is None:
            self.send_bytes(404, b"")
            return

        try:
            with open(record_filename(record_id), "rb") as record:
                body = record.read()
        except FileNotFoundError:
            self.send_bytes(404, b"")
            return
        self.send_bytes(200, body)

    def do_PUT(self):
        record_id = self.record_id()
        if record_id is None:
            self.send_bytes(404, b"")
            return

        try:
            length = int(self.headers.get("Content-Length", "-1"))
        except ValueError:
            length = -1
        if length < 0:
            self.send_bytes(411, b"")
            return

        body = self.rfile.read(length)
        if len(body) != length:
            self.send_bytes(400, b"")
            return

        destination = record_filename(record_id)
        temporary = None
        try:
            fd, temporary = tempfile.mkstemp(dir=RECORDS_DIR, prefix=".record-")
            with os.fdopen(fd, "wb") as record:
                record.write(body)
                record.flush()
                os.fsync(record.fileno())
            os.replace(temporary, destination)
            temporary = None
            directory_fd = os.open(RECORDS_DIR, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary)
                except FileNotFoundError:
                    pass

        self.send_response(204)
        self.send_header("Content-Length", "0")
        self.end_headers()


class Server(http.server.ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True


if __name__ == "__main__":
    Server((HOST, PORT), Handler).serve_forever()

